package com.yonlab.vision;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class AnalyticsTest {
 private Observations.Detection person(float x){return new Observations.Detection(0,"person",.9f,x-.07f,.2f,x+.07f,.7f);}
 private Observations.Face face(int id,float eyes,float yaw){Observations.Face f=new Observations.Face(.2f,.1f,.6f,.8f);f.trackingId=id;f.leftEye=f.rightEye=eyes;f.yaw=yaw;f.pitch=0;f.smile=.8f;return f;}
 @Test public void flowCountsBothDirectionsButIgnoresHysteresisJitter(){Analytics.Flow a=new Analytics.Flow(.5f,.04f,1500);a.update(List.of(person(.38f)),0);a.update(List.of(person(.49f)),100);a.update(List.of(person(.51f)),200);assertEquals(0,a.snapshot().total);a.update(List.of(person(.61f)),300);assertEquals(1,a.snapshot().leftToRight);a.update(List.of(person(.52f)),400);a.update(List.of(person(.48f)),500);assertEquals(1,a.snapshot().total);a.update(List.of(person(.39f)),600);assertEquals(1,a.snapshot().rightToLeft);}
 @Test public void flowFiltersNonPeopleAndDoesNotCountNewOrExpiredTracks(){Analytics.Flow a=new Analytics.Flow();Observations.Detection dog=person(.3f);dog.classId=16;a.update(List.of(dog),0);assertEquals(0,a.snapshot().activeTracks);a.update(List.of(person(.3f)),1);a.update(List.of(person(.7f)),2000);assertEquals(0,a.snapshot().total);}
 @Test public void flowTracksTwoPeopleInOppositeDirections(){Analytics.Flow a=new Analytics.Flow();a.update(List.of(person(.3f),person(.7f)),0);a.update(List.of(person(.42f),person(.58f)),100);a.update(List.of(person(.55f),person(.45f)),200);a.update(List.of(person(.67f),person(.33f)),300);assertEquals(1,a.snapshot().leftToRight);assertEquals(1,a.snapshot().rightToLeft);}
 @Test public void flowResetAndClockRewindClearSession(){Analytics.Flow a=new Analytics.Flow();a.update(List.of(person(.4f)),100);a.update(List.of(person(.6f)),200);assertEquals(1,a.snapshot().total);a.update(List.of(person(.6f)),1);assertEquals(0,a.snapshot().total);a.reset();assertEquals(0,a.snapshot().activeTracks);}
 @Test public void driveMeasuresDurationAndOnlyCountsReopenBlink(){Analytics.Drive a=new Analytics.Drive(1000,800);a.update(List.of(face(1,1,0)),0);a.update(List.of(face(1,0,0)),100);assertFalse(a.update(List.of(face(1,0,0)),1099).drowsy);assertTrue(a.update(List.of(face(1,0,0)),1100).drowsy);assertEquals(0,a.snapshot().blinks);assertEquals(1,a.update(List.of(face(1,1,0)),1200).blinks);}
 @Test public void driveUnknownNoFaceAndIdentityChangeClearTimers(){Analytics.Drive a=new Analytics.Drive(1000,800);a.update(List.of(face(1,0,40)),0);assertTrue(a.update(List.of(face(1,0,40)),1000).drowsy);assertFalse(a.update(List.of(face(1,-1,Float.NaN)),1100).eyesClosed);assertFalse(a.update(List.of(),1200).facePresent);assertEquals(0,a.update(List.of(face(2,1,0)),1300).blinks);a.update(List.of(face(2,0,40)),1400);assertFalse(a.update(List.of(face(3,0,40)),2400).drowsy);}
 @Test public void driveLookAwayRequiresDurationAndKnownAngles(){Analytics.Drive a=new Analytics.Drive(1000,800);a.update(List.of(face(1,1,40)),0);assertFalse(a.update(List.of(face(1,1,40)),799).lookingAway);assertTrue(a.update(List.of(face(1,1,40)),800).lookingAway);assertFalse(a.update(List.of(face(1,1,Float.NaN)),900).lookingAway);}
 @Test public void visitorDwellExcludesAbsenceAndExpiresIdentity(){Analytics.Visitors a=new Analytics.Visitors(1000);a.update(List.of(face(7,1,0)),0);assertEquals(100,a.update(List.of(face(7,1,0)),100).totalDwellMs);a.update(List.of(),200);assertEquals(100,a.update(List.of(face(7,1,0)),300).totalDwellMs);assertEquals(200,a.update(List.of(face(7,1,0)),400).totalDwellMs);assertEquals(2,a.update(List.of(face(7,1,0)),1501).unique);}
 @Test public void visitorDeduplicatesSameFrameAndDoesNotInventUnknownId(){Analytics.Visitors a=new Analytics.Visitors();Analytics.VisitorSnapshot s=a.update(List.of(face(7,1,0),face(7,1,0),face(-1,1,0)),0);assertEquals(1,s.unique);assertEquals(2,s.visible);assertEquals(2,s.smiling);assertEquals(1,s.untracked);a.reset();assertEquals(0,a.snapshot().unique);}
 @Test public void invalidBoxesAndMissingValuesProduceNoEvents(){Analytics.Flow a=new Analytics.Flow();Observations.Detection d=person(Float.NaN);a.update(List.of(d),0);assertEquals(0,a.snapshot().activeTracks);Analytics.Drive b=new Analytics.Drive();Observations.Face f=new Observations.Face(.1f,.1f,.8f,.8f);assertEquals("얼굴 확인",b.update(List.of(f),0).status);assertFalse(b.snapshot().drowsy);}
}
